using AttendanceApi.Data;
using AttendanceApi.DTOs;
using AttendanceApi.Models;
using AttendanceApi.Services;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
namespace AttendanceApi.Controllers;

[ApiController, Authorize]
public class SessionsController(ApplicationDbContext db, AccessService access, AttendanceService attendance) : ControllerBase
{
    [HttpGet("api/classes/{classId:int}/sessions")][ProducesResponseType(typeof(ResponseEnvelope<PageResult<SessionView>>), 200)] public async Task<IActionResult> List(int classId, [FromQuery] ListQuery p) { await access.Class(classId, true); var q = db.Sessions.Where(x => x.CourseClassId == classId); if (!string.IsNullOrWhiteSpace(p.Search)) q = q.Where(x => x.CourseClass.Code.Contains(p.Search) || x.CourseClass.Name.Contains(p.Search) || x.Room.Name.Contains(p.Search)); return Ok(ApiResponse.Ok(await q.OrderBy(x => x.StartAtUtc).Select(x => new SessionView(x.Id, x.CourseClassId, x.RoomId, x.StartAtUtc, x.EndAtUtc, x.AttendanceClosesAtUtc, x.LateAfterMinutes, x.AttendanceState)).PageAsync(p))); }
    static void Validate(SessionRequest r) { ApiSupport.Require(r.StartAtUtc.Offset == TimeSpan.Zero && r.EndAtUtc.Offset == TimeSpan.Zero && r.AttendanceClosesAtUtc.Offset == TimeSpan.Zero, "Thời gian phải ở UTC (Z hoặc +00:00)."); ApiSupport.Require(r.StartAtUtc < r.EndAtUtc && r.AttendanceClosesAtUtc > r.StartAtUtc && r.AttendanceClosesAtUtc <= r.EndAtUtc, "Phải có start < attendanceCloses <= end."); ApiSupport.Require(r.StartAtUtc.AddMinutes(r.LateAfterMinutes) <= r.AttendanceClosesAtUtc, "Ngưỡng trễ phải nằm trong thời gian điểm danh."); }
    [HttpPost("api/classes/{classId:int}/sessions"), Authorize(Roles = "Admin,Lecturer")][ProducesResponseType(typeof(ResponseEnvelope<SessionView>), 201)] public async Task<IActionResult> Create(int classId, SessionRequest r) { Validate(r); await access.Class(classId); ApiSupport.Require(await db.Rooms.AnyAsync(x => x.Id == r.RoomId), "Phòng không tồn tại."); var s = new ClassSession { CourseClassId = classId, RoomId = r.RoomId, StartAtUtc = r.StartAtUtc, EndAtUtc = r.EndAtUtc, AttendanceClosesAtUtc = r.AttendanceClosesAtUtc, LateAfterMinutes = r.LateAfterMinutes }; db.Sessions.Add(s); await db.SaveChangesAsync(); return CreatedAtAction(nameof(Get), new { sessionId = s.Id }, ApiResponse.Ok(s.View())); }
    [HttpGet("api/sessions/{sessionId:int}")][ProducesResponseType(typeof(ResponseEnvelope<SessionView>), 200)] public async Task<IActionResult> Get(int sessionId) => Ok(ApiResponse.Ok((await access.Session(sessionId, true)).View()));
    [HttpPut("api/sessions/{sessionId:int}"), Authorize(Roles = "Admin,Lecturer")][ProducesResponseType(typeof(ResponseEnvelope<SessionView>), 200)] public async Task<IActionResult> Update(int sessionId, SessionRequest r) { Validate(r); await using var tx = await db.Database.BeginTransactionAsync(); var s = await attendance.Lock(sessionId); ApiSupport.Require(s.AttendanceState == AttendanceState.Scheduled, "Chỉ sửa buổi chưa mở điểm danh.", 409); ApiSupport.Require(await db.Rooms.AnyAsync(x => x.Id == r.RoomId), "Phòng không tồn tại."); s.RoomId = r.RoomId; s.StartAtUtc = r.StartAtUtc; s.EndAtUtc = r.EndAtUtc; s.AttendanceClosesAtUtc = r.AttendanceClosesAtUtc; s.LateAfterMinutes = r.LateAfterMinutes; await db.SaveChangesAsync(); await tx.CommitAsync(); return Ok(ApiResponse.Ok(s.View())); }
    [HttpDelete("api/sessions/{sessionId:int}"), Authorize(Roles = "Admin,Lecturer")][ProducesResponseType(typeof(ResponseEnvelope<object>), 200)] public async Task<IActionResult> Delete(int sessionId) { await using var tx = await db.Database.BeginTransactionAsync(); var s = await attendance.Lock(sessionId); ApiSupport.Require(s.AttendanceState == AttendanceState.Scheduled && !await db.Attendances.AnyAsync(x => x.ClassSessionId == sessionId), "Buổi đã được sử dụng; không xóa.", 409); db.Sessions.Remove(s); await db.SaveChangesAsync(); await tx.CommitAsync(); return Ok(ApiResponse.Ok()); }
    [HttpPost("api/sessions/{sessionId:int}/open"), Authorize(Roles = "Admin,Lecturer")][ProducesResponseType(typeof(ResponseEnvelope<SessionView>), 200)] public async Task<IActionResult> Open(int sessionId) => Ok(ApiResponse.Ok(await attendance.Open(sessionId)));
    [HttpPost("api/sessions/{sessionId:int}/close"), Authorize(Roles = "Admin,Lecturer")][ProducesResponseType(typeof(ResponseEnvelope<SessionView>), 200)] public async Task<IActionResult> Close(int sessionId) => Ok(ApiResponse.Ok(await attendance.Close(sessionId)));
    [HttpGet("api/sessions/{sessionId:int}/qr"), Authorize(Roles = "Admin,Lecturer")][ProducesResponseType(typeof(ResponseEnvelope<QrView>), 200)] public async Task<IActionResult> Qr(int sessionId) => Ok(ApiResponse.Ok(await attendance.Qr(sessionId)));
    [HttpGet("api/sessions/{sessionId:int}/attendance"), Authorize(Roles = "Admin,Lecturer")][ProducesResponseType(typeof(ResponseEnvelope<PageResult<AttendanceView>>), 200)] public async Task<IActionResult> Attendance(int sessionId, [FromQuery] ListQuery p) { await access.Session(sessionId); var q = db.Attendances.Where(x => x.ClassSessionId == sessionId); if (!string.IsNullOrWhiteSpace(p.Search)) q = q.Where(x => x.Student.StudentCode.Contains(p.Search) || x.Student.FullName.Contains(p.Search)); return Ok(ApiResponse.Ok(await q.OrderBy(x => x.StudentId).Select(x => new AttendanceView(x.Id, x.ClassSessionId, x.StudentId, x.Status, x.CheckedInAtUtc, x.Latitude, x.Longitude, x.AccuracyMeters, x.DistanceMeters)).PageAsync(p))); }
}
